// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type NotificationAppsProps = Record<string, any>;

const AppItem: React.FC<{
  app: NotificationAppsProps["apps"][0];
  index: number;
  s: number;
  iconSize: number;
  badgeColor: string;
}> = ({ app, index, s, iconSize, badgeColor }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const staggerFrames = 8;
  const startFrame = index * staggerFrames;

  // Spring animation for the whole glassy container popping in
  const containerScale = spring({
    fps,
    frame: frame - startFrame,
    config: { damping: 14, mass: 0.9, stiffness: 180 },
  });

  // Keep it fully invisible before it starts to avoid flash
  const containerOpacity = frame < startFrame ? 0 : 1;

  // Spring for the red notification badge popping in slightly after the container
  const badgeStartFrame = startFrame + 6;
  const badgeScale = spring({
    fps,
    frame: frame - badgeStartFrame,
    config: { damping: 10, mass: 0.6, stiffness: 220 },
  });

  // Interpolate the number counting up
  const countStartFrame = startFrame + 12;
  const countDuration = 30;
  const currentCount = Math.floor(
    interpolate(
      frame,
      [countStartFrame, countStartFrame + countDuration],
      [0, app.targetCount],
      {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      }
    )
  );

  const ratio = iconSize / 170;
  const glassSize = 250 * ratio * s;
  const iconSizeCalculated = iconSize * s;
  const borderRadius = 56 * ratio * s;

  return (
    <div
      style={{
        position: "relative",
        width: glassSize,
        height: glassSize,
        opacity: containerOpacity,
        transform: `scale(${containerScale})`,
        transition: "none",
        // The core glass effect container
        background:
          "linear-gradient(135deg, rgba(255, 255, 255, 0.15) 0%, rgba(255, 255, 255, 0.02) 100%)",
        borderRadius: borderRadius,
        backdropFilter: "blur(20px)",
        WebkitBackdropFilter: "blur(20px)",
        border: `${2 * ratio * s}px solid rgba(255, 255, 255, 0.15)`,
        borderTop: `${3 * ratio * s}px solid rgba(255, 255, 255, 0.4)`, // Stronger top edge highlight
        borderLeft: `${3 * ratio * s}px solid rgba(255, 255, 255, 0.3)`,
        boxShadow: `
          inset ${6 * ratio * s}px ${6 * ratio * s}px ${16 * ratio * s}px rgba(255, 255, 255, 0.2),
          inset -${6 * ratio * s}px -${6 * ratio * s}px ${16 * ratio * s}px rgba(0, 0, 0, 0.1),
          0px ${20 * ratio * s}px ${40 * ratio * s}px rgba(0, 0, 0, 0.4)
        `,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* The App Icon Wrapper */}
      <div
        style={{
          width: iconSizeCalculated,
          height: iconSizeCalculated,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          boxShadow: `0px ${10 * ratio * s}px ${25 * ratio * s}px rgba(0, 0, 0, 0.3)`, // Inner shadow to lift icon off the glass floor
          borderRadius: 40 * ratio * s, // Squirclize any raw square SVGs slightly to match standard app icon looks
          overflow: "hidden",
        }}
      >
        <Img
          src={app.iconUrl}
          style={{
            width: "92%",
            height: "92%",
            objectFit: "contain",
            transition: "none",
          }}
        />
      </div>

      {/* The Notification Badge */}
      <div
        style={{
          position: "absolute",
          top: -15 * ratio * s,
          right: -15 * ratio * s,
          backgroundColor: badgeColor,
          height: 64 * ratio * s,
          minWidth: 64 * ratio * s,
          padding: `0 ${18 * ratio * s}px`,
          borderRadius: 32 * ratio * s,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transform: `scale(${badgeScale})`,
          transformOrigin: "center center",
          boxShadow: `
            0px ${8 * ratio * s}px ${16 * ratio * s}px rgba(0, 0, 0, 0.4),
            inset ${2 * ratio * s}px ${2 * ratio * s}px ${4 * ratio * s}px rgba(255, 255, 255, 0.4)
          `,
          zIndex: 10,
          transition: "none",
        }}
      >
        <span
          style={{
            color: "white",
            fontSize: 36 * ratio * s,
            fontFamily: interFamily,
            fontWeight: 700,
            lineHeight: 1,
            marginTop: 2 * ratio * s, // Optical alignment for Inter numbers
            transition: "none",
          }}
        >
          {currentCount}
        </span>
      </div>
    </div>
  );
};

const NotificationApps: React.FC<NotificationAppsProps> = ({
  backgroundColor = "#081024",
  transparentBackground = false,
  durationInSeconds = 5,
  badgeColor = "#F93A3A",
  iconSize = 170,
  apps = [
    { iconUrl: "https://thesvg.org/icons/instagram/default.svg", targetCount: 23 },
    { iconUrl: "https://thesvg.org/icons/messenger/default.svg", targetCount: 12 },
    { iconUrl: "https://thesvg.org/icons/whatsapp/default.svg", targetCount: 48 },
    { iconUrl: "https://thesvg.org/icons/gmail/default.svg", targetCount: 29 },
    { iconUrl: "https://thesvg.org/icons/telegram/default.svg", targetCount: 9 },
    { iconUrl: "https://thesvg.org/icons/tiktok/dark.svg", targetCount: 2 },
  ],
}) => {
  const { width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;
  const ratio = iconSize / 170;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* Grid Layout Container */}
      <div
        style={{
          display: "flex",
          flexWrap: "wrap",
          justifyContent: "center",
          alignContent: "center",
          gap: `${70 * ratio * s}px ${50 * ratio * s}px`, // Vertical gap slightly larger due to badge overlap
          width: width * 0.75, // Constrain width to dynamic wrapping
          maxWidth: 950 * ratio * s,
        }}
      >
        {apps.map((app, i) => (
          <AppItem
            key={`${app.iconUrl}-${i}`}
            app={app}
            index={i}
            s={s}
            iconSize={iconSize}
            badgeColor={badgeColor}
          />
        ))}
      </div>
    </AbsoluteFill>
  );
};

export default NotificationApps;